package com.familygrowth.application;
import com.familygrowth.domain.Stage26RetentionModels.*;import com.familygrowth.domain.Stage3Models.Actor;import java.time.Clock;import java.util.List;import java.util.UUID;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class Stage26RetentionService {private final Stage3Service auth;private final Stage26RetentionStore store;private final Clock clock;public Stage26RetentionService(Stage3Service auth,Stage26RetentionStore store,Clock clock){this.auth=auth;this.store=store;this.clock=clock;}
 @Transactional(readOnly=true)public RetentionPolicy policy(Actor actor,UUID family,UUID child){auth.requireParent(actor,family);auth.requireChildOrParent(actor,family,child);return store.policy(family,child);}
 @Transactional public RetentionPolicy update(Actor actor,UUID family,UUID child,int days,long expected,String reason){auth.requireParent(actor,family);auth.requireChildOrParent(actor,family,child);String text=reason==null?"":reason.trim();if(days<30||days>365||text.isBlank()||text.length()>240)throw new IllegalArgumentException("Retention policy is invalid");return store.updatePolicy(family,child,actor.actorId(),days,expected,text,clock.instant());}
 @Transactional public RetentionRun run(Actor actor,UUID family,UUID child){auth.requireParent(actor,family);auth.requireChildOrParent(actor,family,child);return store.run(family,child,store.policy(family,child).usageDetailDays(),"PARENT",actor.actorId(),clock.instant());}
 @Scheduled(initialDelayString="${family-growth.retention.initial-delay-ms:21600000}",fixedDelayString="${family-growth.retention.interval-ms:86400000}")@Transactional public void scheduled(){for(RetentionTarget target:store.targets())store.run(target.familyId(),target.childId(),target.usageDetailDays(),"SCHEDULED",null,clock.instant());}
}
